    "explain": "Code ของ WOAH (ข้อกำหนด) มุ่งป้องกันควบคุมโรคในสัตว์และโรคติดต่อระหว่างสัตว์และมนุษย์ ทำให้การค้าสัตว์และผลิตภัณฑ์จากสัตว์ปลอดภัย ส่งเสริมสวัสดิภาพสัตว์ และวางหลักงานบริการสัตวแพทย์ การควบคุมการขนส่งสัตว์อย่างปลอดภัย การป้องกันการแพร่กระจายของเชื้อ และการจัดการสวัสดิภาพสัตว์จึงอยู่ในวัตถุประสงค์ ส่วนการเพิ่มปริมาณสัตว์เพื่อการค้าไม่ใช่เป้าหมายของ code",
