    "explain": "การควบคุมอาหารที่มาจากสัตว์น้ำของไทยแบ่งระหว่างสองกระทรวง กระทรวงเกษตรและสหกรณ์ (กรมประมง กรมปศุสัตว์ มกอช.) ดูแลการผลิตขั้นต้นด้านความปลอดภัยและคุณภาพ การค้าที่เน้นการส่งออก และความมั่นคงทางอาหาร ส่วนกระทรวงสาธารณสุข (เช่น อย.) ดูแลการคุ้มครองผู้บริโภค การผลิตและการแปรรูป การค้าที่เน้นการนำเข้า และตลาดในประเทศรวมทั้งผู้ให้บริการด้านอาหาร คู่ที่ถูกจึงเป็นกระทรวงเกษตรและสหกรณ์กับความมั่นคงทางอาหารและการส่งออก",
