    "explain": "อาการกล้ามเนื้อขาวขุ่นในกุ้งขาวแวนนาไมมีสาเหตุหลักจาก IMNV ซึ่งรายงานเฉพาะในกุ้งขาวแวนนาไม และต้องแยกจากสาเหตุอื่น ได้แก่ ความเครียด การขาดแร่ธาตุ การติดเชื้อแบคทีเรีย และ microsporidian ซึ่งเคยจัดเป็นโปรโตซัวแต่ปัจจุบันจัดว่าใกล้เคียงเชื้อรา ส่วน MrNV เป็นสาเหตุของโรคหางขาวในกุ้งก้ามกราม (Macrobrachium rosenbergii) ทำให้กล้ามเนื้อส่วนท้องและหางขาวขุ่นในกุ้งก้ามกรามวัยอ่อน และไม่อยู่ในรายการสาเหตุที่ต้องแยกจาก IMNV ในกุ้งขาวแวนนาไม",
