    "q": "เมื่อเปรียบเทียบระบบภูมิคุ้มกันโรคในปลากับสัตว์ที่มีกระดูกสันหลังชั้นสูง พบว่าระบบภูมิคุ้มกันโรคในปลา...",
    "options": [
      "mucus เป็นส่วนของ innate immune response ที่มีบทบาทสำคัญ แต่ไม่พบในสัตว์มีกระดูกสันหลังชั้นสูง",
      "การทำงานของ humoral factors คล้ายคลึงกับสัตว์มีกระดูกสันหลังชั้นสูง",
      "Cell-mediated immune response ทำหน้าที่ phagocytic activity แต่ไม่ทำหน้าที่ antigen presentation ดังเช่นในสัตว์มีกระดูกสันหลังชั้นสูง",
      "Humoral factors ที่สำคัญในระบบภูมิคุ้มกันโรคในปลา คือ antibody หรือ immunoglobulin ซึ่งมี 2 isotypes",
      "ถูกทุกข้อ"
    ],
    "answer": 0,
    "explain": "เมือก (mucus) จาก goblet cell ที่ผิวปลาเป็นด่านภูมิคุ้มกันแบบไม่จำเพาะที่สำคัญมากในปลา มีการผลิตใหม่ตลอดเวลา ช่วยการเคลื่อนที่ ช่วยควบคุมสมดุลน้ำและเกลือแร่ และขจัดโลหะหนัก ปรสิต และสิ่งระคายเคือง โดยมี Ig complement และ lysozyme อยู่ในเมือก ข้อความอื่นผิด ปลามี MHC และ phagocyte ของปลานำเสนอแอนติเจนได้ humoral immunity ของปลาต่างจากสัตว์เลี้ยงลูกด้วยนม เพราะ immunoglobulin หลักของปลาคือ IgM ในรูป monomer tetramer และ pentamer ขณะที่สัตว์เลี้ยงลูกด้วยนมมี IgG IgA IgM IgE และ IgD ไม่ได้แบ่งเป็นสอง isotype ตามที่ข้อความระบุ ตัวเลือกถูกทุกข้อจึงใช้ไม่ได้",
