    "type": "mcq",
    "examScope": "final",
    "q": "ในกรณีที่ประเทศไทยต้องการ “ประกาศสถานะปลอดโรค Tilapia Lake Virus (TiLV)” เพื่อส่งเสริมการส่งออกปลานิลไปยังประเทศคู่ค้า หน่วยงานใดของไทยมีบทบาทสำคัญที่สุดในการจัดทำข้อมูลและขอการรับรองสถานะปลอดโรคจากองค์การสุขภาพสัตว์โลก (WOAH) และเหตุผลใดที่อธิบายได้ดีที่สุดว่าทำไมหน่วยงานนี้จึงมีความเหมาะสมในการดำเนินการดังกล่าว",
    "options": [
      "กรมประมง (Department of Fisheries) — เนื่องจากเป็นหน่วยงานที่รับผิดชอบโดยตรงด้านการเพาะเลี้ยงสัตว์น้ำและระบบเฝ้าระวังโรคสัตว์น้ำของประเทศ",
      "กรมปศุสัตว์ (Department of Livestock Development) — เพราะเป็น Veterinary Authority ของประเทศไทย และเป็นผู้แทนถาวรของไทยใน WOAH ซึ่งมีอำนาจเสนอขอรับรองสถานะปลอดโรคอย่างเป็นทางการ",
      "สำนักงานมาตรฐานสินค้าเกษตรและอาหารแห่งชาติ (มกอช.) — เพราะเป็น Focal point ด้านมาตรฐานสินค้าการเกษตรของไทยและเป็นผู้กำหนด GAP สำหรับฟาร์มปลานิล",
      "กรมควบคุมโรค (Department of Disease Control) — เพราะรับผิดชอบด้านโรคติดต่อที่อาจมีผลกระทบต่อสุขภาพคนและสัตว์ (One Health)",
      "สมาคมสัตวแพทย์สัตว์น้ำไทย — เพราะเป็นผู้เชี่ยวชาญเฉพาะทางด้านโรคสัตว์น้ำและสามารถจัดทำรายงานวิชาการสนับสนุนการขอรับรองสถานะโรคได้"
    ],
    "answer": 1,
    "explain": "สำหรับโรคสัตว์น้ำ ประเทศเป็นผู้ประกาศสถานะปลอดโรคของประเทศ โซน หรือคอมพาร์ตเมนต์เองตามเกณฑ์ใน Aquatic Code แล้วยื่นเรื่องต่อ WOAH ผ่านผู้แทนถาวร (Delegate) ซึ่งของไทยคือกรมปศุสัตว์ในฐานะ Veterinary Authority กรมประมงเป็น competent authority ด้านสุขอนามัยสัตว์น้ำที่เฝ้าระวังโรคและจัดทำข้อมูลสนับสนุน แต่ไม่ได้เป็นผู้แทนของประเทศใน WOAH มกอช. เป็น focal point ด้านมาตรฐานสินค้าเกษตร กรมควบคุมโรคอยู่ฝั่งกระทรวงสาธารณสุข และสมาคมวิชาชีพทำได้เพียงสนับสนุนข้อมูลทางวิชาการ เหตุผลที่ตรงที่สุดจึงเป็นการเป็น Veterinary Authority และผู้แทนถาวรของไทยใน WOAH",
