    "explain": "WAHIS (World Animal Health Information System) คือระบบข้อมูลสุขภาพสัตว์โลกของ WOAH ที่หน่วยงานผู้มีอำนาจหน้าที่ของประเทศสมาชิกใช้รายงานโรคแบบ real-time ผ่านอินเทอร์เน็ต ทั้งโรคในบัญชีรายชื่อของ WOAH และเหตุการณ์ทางระบาดวิทยาผ่าน alert messages เพื่อให้ป้องกันและควบคุมโรคได้ทันท่วงที ชื่ออื่นในตัวเลือกไม่ใช่ระบบรายงานโรคของ WOAH",
